package gcdofstrings

import (
	"leetcode/common"
	"testing"
)

func Test1(t *testing.T) {
	common.RunTests(
		t,
		gcdOfStrings,
		[]common.TestCase{
			{
				Args: []any{"ABCABC","ABC"},
				Expected: "ABC",
			},
			{
				Args: []any{"ABABAB","ABAB"},
				Expected: "AB",
			},
			{
				Args: []any{"LEET","CODE"},
				Expected: "",
			},
			{
				Args: []any{"ABABABAB","ABAB"},
				Expected: "ABAB",
			},
				{
				Args: []any{"",""},
				Expected: "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA",
			},
		},
	)
}